(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const btns = Array.from(document.querySelectorAll('button')).filter(b => /send\s*otp/i.test((b.innerText||'').replace(/\s+/g,' ')));
  let clicked = 0, lastText = '';
  for (const b of btns) {
    if (b.offsetParent === null) {
      const anc = b.closest('[style]');
      if (anc) anc.removeAttribute('style');
      b.closest('.d-none,.hidden,[hidden]')?.removeAttribute('hidden');
    }
    try { b.click(); clicked++; lastText = (b.innerText||'').replace(/\s+/g,' '); } catch(e) {}
  }
  await sleep(4000);
  const news = (document.body.innerText||'').replace(/\s+/g,' ');
  const m = news.match(/(sent|resend|seconds|wait|not received[^.]*)/i);
  const countdown = Array.from(document.querySelectorAll('div,span,p,button')).map(e=>(e.innerText||'').replace(/\s+/g,' ').trim()).filter(t=>/^\d{1,2}\s*s(ec)?\.?$/i.test(t)).slice(0,4);
  return JSON.stringify({clicked, lastText, snippet: m ? m[0].slice(0,120) : null, countdown, otpSectionStill: /enter the 6-digit otp/i.test(news)});
})()
